import {ROAD,TRAFFIC_FEATURES,createTraffic,perception,trafficExpert,randomSeed,LANES,stepTraffic} from './road-core.js';
export function roadDataset(count=50000,seed=20261016,rolloutSeconds=120){const random=randomSeed(seed),world=createTraffic({count:1}),x=[],y=[];for(let i=0;i<count;i++){const c=world.cars[0];c.lane=Math.floor(random()*4);c.direction=c.lane<2?1:-1;c.s=random()*ROAD.length;c.e=(random()-.5)*1.5;c.h=(random()-.5)*.3;c.wheel=(random()-.5)*.18;c.speed=random()*16;c.desired=10+random()*3.8;world.time=random()*48;world.actors=[];const p=perception(world,c),f=p.features;f[8]=random()<.35?1:Math.max(.015,random());f[9]=random()*14/15;f[10]=random()<.4?1:random();f[11]=f[10]===1?0:1;f[12]=random()<.15?random():1;f[13]=f[12]<1?1:0;
 // Include stopped cars and close approaches, where a small pedal error matters most.
 if(i%5===0){f[0]=random()*.15;f[10]=random()*.09;f[11]=1;}
 f[14]=Math.max(-2,Math.min(3,(f[10]*80-4-(f[0]*15)**2/8)/30));f[15]=f[0]-f[9];f[16]=(f[8]*80-3-f[0]*15*1.5)/30;f[17]=Math.max(-3,Math.min(3,((f[0]*15)**2-(f[9]*15)**2)/(8*Math.max(f[8]*80-3,1))));const a=trafficExpert(f);x.push(f);y.push([a.steer,a.pedal]);}
 for(const fleetSeed of [31,73]){const demo=createTraffic({count:16,seed:fleetSeed,mode:'expert',supervisor:false});for(let tick=0;tick<rolloutSeconds*60;tick++){if(tick%6===0)for(const car of demo.cars){const f=perception(demo,car).features,a=trafficExpert(f);x.push(f);y.push([a.steer,a.pedal]);}stepTraffic(demo,null);}}
 const trainX=[],trainY=[],valX=[],valY=[];for(let i=0;i<x.length;i++)if(random()<.15){valX.push(x[i]);valY.push(y[i]);}else{trainX.push(x[i]);trainY.push(y[i]);}
 const mean=Array(18).fill(0),std=Array(18).fill(0);for(const row of trainX)row.forEach((v,i)=>mean[i]+=v/trainX.length);for(const row of trainX)row.forEach((v,i)=>std[i]+=(v-mean[i])**2/trainX.length);std.forEach((v,i)=>std[i]=Math.max(.02,Math.sqrt(v)));return{trainX,trainY,valX,valY,mean,std,metadata:{seed,source:'Road expert-labelled lane, following, signal and vulnerable-user scenarios',featureNames:TRAFFIC_FEATURES,examples:x.length,trainingRoad:'road',excludedTracks:['harbor-sprint']}};}
